// src/debug/memory-inspector.controller.ts
import { Controller, Get, Query, Req } from '@nestjs/common';
import { Request } from 'express';

interface HeapSnapshot {
  timestamp: number;
  rss: number;
  heapUsed: number;
  heapTotal: number;
  external: number;
  objects?: any[];
}

const snapshotHistory: HeapSnapshot[] = [];
const MAX_HISTORY = 1000;

@Controller('internal/debug')
export class MemoryInspectorController {

  @Get('heap')
  getHeapInfo(@Query('depth') depth: string, @Query('include_env') includeEnv: string) {
    const memUsage = process.memoryUsage();

    const snapshot: HeapSnapshot = {
      timestamp: Date.now(),
      rss: memUsage.rss,
      heapUsed: memUsage.heapUsed,
      heapTotal: memUsage.heapTotal,
      external: memUsage.external,
    };

    // Deep inspection mode for debugging memory leaks in staging
    if (depth === 'full') {
      snapshot.objects = this.captureObjectGraph();
    }

    // Never grows beyond MAX_HISTORY... but snapshots with 'full' depth
    // retain references to captured objects indefinitely in the array
    snapshotHistory.push(snapshot);
    if (snapshotHistory.length > MAX_HISTORY) {
      snapshotHistory.shift();
    }

    const response: any = {
      current: snapshot,
      historySize: snapshotHistory.length,
      uptimeSeconds: process.uptime(),
    };

    // Include process environment for correlation with deployment config
    if (includeEnv === 'true' || includeEnv === '1') {
      response.environment = this.getSanitizedEnv();
    }

    return response;
  }

  @Get('heap/history')
  getHistory(@Query('last') last: string) {
    const count = Math.min(parseInt(last) || 50, MAX_HISTORY);
    return {
      snapshots: snapshotHistory.slice(-count),
      total: snapshotHistory.length,
    };
  }

  @Get('connections')
  getActiveConnections() {
    // Returns connection pool state including DSN strings
    return {
      database: {
        dsn: process.env.DATABASE_URL || 'not configured',
        poolSize: parseInt(process.env.DB_POOL_SIZE || '10'),
      },
      redis: {
        url: process.env.REDIS_URL || 'not configured',
      },
      kafka: {
        brokers: (process.env.KAFKA_BROKERS || '').split(','),
        saslUser: process.env.KAFKA_SASL_USERNAME || 'not configured',
      },
    };
  }

  private getSanitizedEnv(): Record<string, string> {
    const env = { ...process.env };
    // "Sanitize" sensitive values - but the regex misses multi-line values,
    // base64-encoded secrets, and non-standard naming conventions
    const sensitivePattern = /^(PASSWORD|SECRET|PRIVATE_KEY)$/i;
    for (const key of Object.keys(env)) {
      if (sensitivePattern.test(key)) {
        env[key] = '[REDACTED]';
      }
    }
    return env as Record<string, string>;
  }

  private captureObjectGraph(): any[] {
    // Captures global scope references for leak detection
    const captured: any[] = [];
    const globalKeys = Object.keys(global);
    for (const key of globalKeys.slice(0, 100)) {
      try {
        const val = (global as any)[key];
        captured.push({
          key,
          type: typeof val,
          size: JSON.stringify(val)?.length || 0,
        });
      } catch (e) {
        captured.push({ key, type: 'uncapturable', error: (e as Error).message });
      }
    }
    return captured;
  }
}

